package com.github.adriianh.core.platform

import com.github.adriianh.core.domain.model.update.UpdateInstallMethod
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull

class DesktopInstallTest {
    @Test
    fun `parseMarker keeps key value pairs and skips comments and blanks`() {
        val values =
            DesktopInstall.parseMarker(
                """
                # Generated by the Melo installer.
                MELO_COMPONENT=gui

                MELO_SCOPE = user
                MELO_INSTALL_DIR=/home/melo/.local/share/melo-gui
                """.trimIndent(),
            )

        assertEquals("gui", values["MELO_COMPONENT"])
        assertEquals("user", values["MELO_SCOPE"])
        assertEquals("/home/melo/.local/share/melo-gui", values["MELO_INSTALL_DIR"])
    }

    @Test
    fun `detect prefers the appimage the process was started from`() {
        val method =
            DesktopInstall.detect(
                environment(appImage = APPIMAGE_PATH),
                exists = { it == APPIMAGE_PATH },
                readFile = { null },
            )

        assertEquals(UpdateInstallMethod.APPIMAGE, method)
    }

    @Test
    fun `detect identifies a portable install from its marker`() {
        val method =
            DesktopInstall.detect(
                environment(),
                exists = { false },
                readFile = ::markerOrNull,
            )

        assertEquals(UpdateInstallMethod.TARBALL, method)

        val install = DesktopInstall.portableInstall(environment(), ::markerOrNull)
        assertNotNull(install)
        assertEquals("$HOME/.local/share/melo-gui", install.installDir)
        assertEquals("$HOME/.local/bin", install.binDir)
        assertEquals("user", install.scope)
    }

    @Test
    fun `detect ignores markers written for another component`() {
        val method =
            DesktopInstall.detect(
                environment(),
                exists = { false },
                readFile = { path -> if (path == MARKER_PATH) "MELO_COMPONENT=tui" else null },
            )

        assertEquals(UpdateInstallMethod.UNKNOWN, method)
    }

    @Test
    fun `detect recognises a pre-marker per-user install from the app dir`() {
        val method =
            DesktopInstall.detect(
                environment(processCommand = "$HOME/.local/share/melo-gui/lib/runtime/bin/java"),
                exists = { false },
                readFile = { null },
            )

        assertEquals(UpdateInstallMethod.TARBALL, method)
    }

    @Test
    fun `detect treats an install under opt as package managed`() {
        val method =
            DesktopInstall.detect(
                environment(processCommand = "/opt/melo-gui/lib/runtime/bin/java"),
                exists = { false },
                readFile = { null },
            )

        assertEquals(UpdateInstallMethod.PACKAGE_MANAGER, method)
    }

    @Test
    fun `detect resolves the app dir from the classpath too`() {
        val method =
            DesktopInstall.detect(
                environment(classpath = "/opt/melo-gui/lib/app/melo.jar"),
                exists = { false },
                readFile = { null },
            )

        assertEquals(UpdateInstallMethod.PACKAGE_MANAGER, method)
    }

    @Test
    fun `resolveAppDir reads the app dir from the jpackage launcher command`() {
        val appDir = DesktopInstall.resolveAppDir("$HOME/Applications/Melo/bin/Melo", "")

        assertEquals("$HOME/Applications/Melo", appDir)
    }

    @Test
    fun `appImagePath requires the file to exist`() {
        assertNull(DesktopInstall.appImagePath(mapOf("APPIMAGE" to APPIMAGE_PATH)) { false })
        assertEquals(APPIMAGE_PATH, DesktopInstall.appImagePath(mapOf("APPIMAGE" to APPIMAGE_PATH)) { true })
    }

    private fun markerOrNull(path: String): String? = MARKER.takeIf { path == MARKER_PATH }

    private fun environment(
        osName: String = "linux",
        home: String = HOME,
        appImage: String? = null,
        processCommand: String? = null,
        classpath: String = "",
    ) = DesktopInstallEnvironment(
        osName = osName,
        home = home,
        env = if (appImage == null) emptyMap() else mapOf("APPIMAGE" to appImage),
        processCommand = processCommand,
        classpath = classpath,
    )

    private companion object {
        const val HOME = "/home/melo"
        const val APPIMAGE_PATH = "/home/melo/Applications/Melo.AppImage"
        const val MARKER_PATH = "$HOME/.local/share/melo-gui/.melo-install"
        val MARKER =
            """
            # Generated by the Melo installer.
            MELO_COMPONENT=gui
            MELO_SCOPE=user
            MELO_INSTALL_DIR=$HOME/.local/share/melo-gui
            MELO_BIN_DIR=$HOME/.local/bin
            """.trimIndent()
    }
}
